const authListarAcessos = `-- name: AuthListarAcessos :many

SELECT empresa_id, usuario_id
FROM plataforma.acesso_empresa
WHERE identidade_id = $1 AND habilitado
ORDER BY empresa_id
`

type AuthListarAcessosRow struct {
	EmpresaID uuid.UUID `json:"empresa_id"`
	UsuarioID uuid.UUID `json:"usuario_id"`
}

// ------------------------------------------------------------ acesso_empresa
func (q *Queries) AuthListarAcessos(ctx context.Context, identidadeID uuid.UUID) ([]AuthListarAcessosRow, error) {
	rows, err := q.db.Query(ctx, authListarAcessos, identidadeID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AuthListarAcessosRow{}
	for rows.Next() {
		var i AuthListarAcessosRow
		if err := rows.Scan(&i.EmpresaID, &i.UsuarioID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

